import{_ as o,o as r,c as d,ag as e}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"安卓电视去广告改造：视频说\\"豆包一键爆改\\"，实测真身是 cleanyourtv","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-tools/android-tv-debloat-cleanyourtv.md","filePath":"topics/ai-tools/android-tv-debloat-cleanyourtv.md"}'),n={name:"topics/ai-tools/android-tv-debloat-cleanyourtv.md"};function s(a,t,l,g,i,u){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="安卓电视去广告改造-视频说-豆包一键爆改-实测真身是-cleanyourtv" tabindex="-1">安卓电视去广告改造：视频说&quot;豆包一键爆改&quot;，实测真身是 cleanyourtv <a class="header-anchor" href="#安卓电视去广告改造-视频说-豆包一键爆改-实测真身是-cleanyourtv" aria-label="Permalink to &quot;安卓电视去广告改造：视频说&quot;豆包一键爆改&quot;，实测真身是 cleanyourtv&quot;">​</a></h1><blockquote><p><strong>来源</strong>：2026-10-19 飞书分享（豆包 AI 一键爆改安卓老电视、去广告、对标 Apple TV 的教程） <strong>性质</strong>：开源项目实测核查 —— 技术骨架为真，但<strong>关键环节有明显偏差</strong>，动手前必读 关键词：安卓电视、Google TV、去广告、ADB调试、预装软件、启动器、Apple TV、cleanyourtv、tv-vibehack、Claude Code、AI Agent、pm disable-user、设备主权、WiFi调试、5555端口、变砖风险</p></blockquote><hr><h2 id="一、原文-保留" tabindex="-1">一、原文（保留） <a class="header-anchor" href="#一、原文-保留" aria-label="Permalink to &quot;一、原文（保留）&quot;">​</a></h2><p>视频分享了如何利用豆包 AI 一键爆改安卓老电视，实现去广告并对标 Apple TV 体验的实用教程。具体操作非常简单，只需在豆包中输入指定指令并替换为自己的电视型号，它就会自动调用开源项目 tv-vibehack。AI 会指导你开启电视的 ADB 调试，并通过 WiFi 连接电脑，全程自动卸载预装软件、安装纯净启动器，还会自动备份恢复脚本。改造后的电视开机干净无广告，系统响应速度大幅提升。不过，由于不同品牌电视的系统兼容性存在差异，建议大家在动手前先了解自家设备的具体情况。</p><hr><h2 id="二、事实核查-技术骨架为真-但三处关键偏差" tabindex="-1">二、事实核查：技术骨架为真，但三处关键偏差 <a class="header-anchor" href="#二、事实核查-技术骨架为真-但三处关键偏差" aria-label="Permalink to &quot;二、事实核查：技术骨架为真，但三处关键偏差&quot;">​</a></h2><table tabindex="0"><thead><tr><th>视频说法</th><th>实测</th><th>判定</th></tr></thead><tbody><tr><td>&quot;在 AI 里输入指令 + 换型号，就能自动化&quot;</td><td>✅ 真有这个套路：<strong><code>cleanyourtv</code> 仓库里就是一份 <code>PROMPT.md</code></strong>（原文：粘进&quot;Claude Code 或带 shell 能力的编码助手&quot;）</td><td>✅ 成立，但<strong>主力是 Claude Code 类 agent，不是豆包</strong></td></tr><tr><td>&quot;<strong>自动调用</strong>开源项目 tv-vibehack&quot;</td><td>⚠️ 被广泛使用的是 <strong><code>Gathin23/cleanyourtv</code>（★4310）</strong>；<code>tv-vibehack</code> 是 <strong>★26 的新仓（创建于 2026-10-19，即视频当天）</strong>，0 issue / 2 fork，README 满是&quot;100% fail-safe&quot;营销 badge</td><td>⚠️ <strong>项目名很可能张冠李戴</strong></td></tr><tr><td>&quot;全程<strong>自动卸载</strong>预装软件&quot;</td><td>⚠️ 官方提示词明令：<strong>用 <code>pm disable-user --user 0</code> 禁用，绝不卸载系统包</strong>；README 卖点正是 <strong>&quot;nothing uninstalled, one-line restore&quot;</strong></td><td>❌ <strong>反了</strong>：核心是<strong>禁用</strong>（可一键恢复）而非卸载</td></tr><tr><td>&quot;全程自动&quot;</td><td>⚠️ 真实流程需要<strong>你手动</strong>：电视上连点 Build 7 次开开发者选项、开 USB/网络调试、<strong>在电视上点&quot;允许 USB 调试&quot;弹窗</strong>；agent 还要<strong>逐步截图验证</strong>、就流媒体/语音助手等问你偏好</td><td>⚠️ <strong>是&quot;AI 指挥 + 你按键&quot;的协作，不是无人值守</strong></td></tr><tr><td>&quot;对标 Apple TV 体验&quot;</td><td>✅ 与 cleanyourtv 描述一致（&quot;a clean launcher that looks like an Apple TV&quot;，launcher 仅 280 KB）</td><td>✅ 成立</td></tr><tr><td>&quot;不同品牌兼容性有差异&quot;</td><td>✅ 原文明确：<strong>支持</strong>小米/TCL/海信/索尼/一加/真我/Nvidia Shield 等 Android TV &amp; Google TV；<strong>不支持三星 Tizen、LG webOS、Fire TV</strong></td><td>✅ 成立且值得强调</td></tr></tbody></table><hr><h2 id="三、真实项目对照-2026-10-19-实测数据" tabindex="-1">三、真实项目对照（2026-10-19 实测数据） <a class="header-anchor" href="#三、真实项目对照-2026-10-19-实测数据" aria-label="Permalink to &quot;三、真实项目对照（2026-10-19 实测数据）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>仓库</th><th>★</th><th>许可</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td><strong>Gathin23/cleanyourtv</strong></td><td><strong>4,310</strong></td><td>MIT</td><td>创建 10-17，活跃</td><td><strong>视频的真身</strong>：<code>PROMPT.md</code> + <strong>52 个已验证机型清单</strong>（examples/，22 品牌 11 语言）+ 280 KB launcher；fork 511</td></tr><tr><td>ToomRamcharan/tv-vibehack</td><td>26</td><td>NOASSERTION</td><td>创建 <strong>10-19</strong>（当天）</td><td>视频点名的项目。极新、0 issue，README 为营销式排版 → <strong>未经社区验证</strong></td></tr><tr><td>pulgagr/tv-vibehack-firetv</td><td>9</td><td>MIT</td><td>10-17</td><td>单机型实践记录（Insignia Fire TV），内容实在</td></tr><tr><td>mclhm8182/tvhome-zh</td><td>54</td><td>NOASSERTION</td><td>活跃</td><td><strong>中文版 Apple TV 风格 launcher</strong>，现成 APK 不用编译</td></tr><tr><td>seun-novodev/android-tv-debloat-toolkit</td><td>745</td><td>MIT</td><td>06-28</td><td>轻量工具箱（去预装 + 装 APK）</td></tr><tr><td>0x192/universal-android-debloater</td><td>20,172</td><td>GPL-3.0</td><td>⚠️ <strong>2024-08 停更</strong></td><td>老牌桌面 GUI 去预装工具</td></tr><tr><td>Universal-Debloater-Alliance/...-next-generation</td><td>9,481</td><td>GPL-3.0</td><td>活跃</td><td>上面那个的<strong>社区接棒版</strong>（仍在维护，认这个）</td></tr></tbody></table><blockquote><p><strong>一句话</strong>：想动手就认 <strong>cleanyourtv</strong>（★4310 + 52 机型清单 + PROMPT.md），别被 ★26 的同名新仓带偏。</p></blockquote><hr><h2 id="四、真实操作链-提炼自-prompt-md-含真实坑" tabindex="-1">四、真实操作链（提炼自 PROMPT.md，含真实坑） <a class="header-anchor" href="#四、真实操作链-提炼自-prompt-md-含真实坑" aria-label="Permalink to &quot;四、真实操作链（提炼自 PROMPT.md，含真实坑）&quot;">​</a></h2><ol><li><strong>电视侧准备</strong>：设置 → 关于 → 连按 <strong>Build 7 次</strong> → 开发者选项 → 开 <strong>USB 调试</strong>（有&quot;网络调试&quot;也开）。保持电视开机。</li><li><strong>连接</strong>：在同一 WiFi 下用 <strong>ADB over WiFi，端口 5555</strong> 连电视。</li><li><strong>先备份，后动手</strong>：完整包列表 / 已禁用列表 / <code>getprop</code> / 全部设置 → 存备份目录，并<strong>写好恢复脚本</strong>。</li><li><strong>分类再禁用</strong>：把包分成①厂商遥测分析②厂商内容与广告服务（如小米 PatchWall、推荐位）③无用后台④预装应用⑤流媒体应用；<strong>只禁用前几类</strong>。</li><li><strong>小批量 + 中间截图</strong>：一批禁完截图确认，因为<strong>一批可能带倒关键包且事后分不清是哪个</strong>。</li><li><strong>绝不碰</strong>：TV app / HDMI 与调谐器输入服务、输入源菜单、遥控与蓝牙配对、屏幕键盘、Play Store 与 Play Services。</li><li><strong>流媒体/语音助手/Chromecast/Miracast/更新服务</strong>：<strong>先问用户用不用</strong>，只禁没勾的。</li><li>最后：装干净启动器（设为默认 Home）。</li></ol><p><strong>真实踩坑（原文明确记录的）</strong>：</p><ul><li><strong>macOS 上 <code>adb</code> 报 &quot;No route to host&quot;</strong>，即使端口开着 → 是 <strong>macOS 本地网络隐私权限</strong>拦截，别去 debug，改用 Python <code>adb-shell</code> 包做客户端；大文件 push 挂住就 base64 分块传 + 校验 md5。</li><li><strong>Android 14 上 <code>adb install</code> 会挂住</strong>（在等屏幕确认）→ 改为 push APK 后 <code>pm install -r</code>。</li><li><strong><code>pm</code> 命令一次只跑一条</strong>：链式命令会在第一条之后<strong>静默停止</strong>。</li><li><strong>开 USB 调试期间，部分设备会切断 USB 口供电</strong> → 插在上面的音箱/U 盘会&quot;坏掉&quot;，事后记得关掉调试。</li></ul><hr><h2 id="五、风险与边界-按客观打折写" tabindex="-1">五、风险与边界（按客观打折写） <a class="header-anchor" href="#五、风险与边界-按客观打折写" aria-label="Permalink to &quot;五、风险与边界（按客观打折写）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>说明</th><th>应对</th></tr></thead><tbody><tr><td><strong>ADB 5555 是著名攻击面</strong></td><td>开网络 ADB = 在局域网暴露一个 <strong>shell</strong>（无认证，仅靠配对弹窗）；家庭网络若被入侵/有恶意设备，等于交出电视</td><td>用完<strong>关掉网络调试</strong>；别在公共/不可信 WiFi 下开；不要做端口转发</td></tr><tr><td><strong>禁错关键包 = 电视半残</strong></td><td>厂商包名往往不说明用途（如&quot;输入源菜单&quot;被禁 → 遥控器切不了 HDMI）</td><td>禁前 <code>dumpsys package</code> 查它的 activity/service；<strong>小批量 + 截图</strong></td></tr><tr><td><strong>厂商 OTA 更新可能受影响</strong></td><td>禁用更新服务后不再自动升级（有人正是为此，有人反而想要更新）</td><td>明确取舍；备份后仍可用恢复脚本还原</td></tr><tr><td><strong>不同固件差异大</strong></td><td>即使是同一品牌，不同年份/固件包名都不同</td><td>对号入座用 examples/ 里的<strong>机型清单</strong>；没清单就小步试</td></tr><tr><td><strong>保修/合规</strong></td><td>一般不影响硬件保修，但删改系统配置属自担风险</td><td>先备份，保留恢复路径</td></tr><tr><td><strong>&quot;100% fail-safe&quot;是宣传语</strong></td><td>★26 那仓的 badge 这么写；官方提示词反而通篇强调<strong>谨慎、备份、小批量、逐步验证</strong></td><td>信后者</td></tr></tbody></table><hr><h2 id="六、这条内容本身的元教训" tabindex="-1">六、这条内容本身的元教训 <a class="header-anchor" href="#六、这条内容本身的元教训" aria-label="Permalink to &quot;六、这条内容本身的元教训&quot;">​</a></h2><p><strong>AI 生成/口播的&quot;科普&quot;最爱错在专有名词与量级</strong>：大方向对（去广告、ADB、换 launcher），但把**★4310 的项目说成 ★26 的同名新仓**、把**&quot;禁用&quot;说成&quot;卸载&quot;**。核实成本极低（一次 GitHub API 查询），不核实就会被带去做错事（真卸载了系统包）。→ 与库内&quot;媒体渲染 vs 仓库事实&quot;是同一条原则。</p><hr><p>关键词：安卓电视、Google TV、去广告、ADB调试、预装软件、启动器、Apple TV、cleanyourtv、tv-vibehack、Claude Code、AI Agent、pm disable-user、设备主权、WiFi调试、5555端口、变砖风险、Shizuku、debloat、PROMPT.md</p><p>关联：<code>topics/ai-tools/index.md</code>（本主题评测原则：实测数据优先、媒体渲染 vs 仓库事实）、<code>topics/cybersecurity/</code>（<strong>开放 ADB 5555 端口 = 局域网暴露 shell</strong>，属攻击面管理）、<code>topics/ai-system-architecture/</code>（AI 生成内容的核验，Echo Gap 同源原则）</p>',26)])])}const p=o(n,[["render",s]]);export{h as __pageData,p as default};
